def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = {}
    for row in grid:
        for v in row: freq[v] = freq.get(v, 0) + 1
    # The barrier is a full row or column whose color occurs exactly along that line.
    rowbar = next((r for r in range(h) if len(set(grid[r])) == 1 and freq[grid[r][0]] == w), None)
    colbar = next((c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and freq[grid[0][c]] == h), None)
    if rowbar is not None:
        barrier = grid[rowbar][0]
    else:
        barrier = grid[0][colbar]
    bg = max((v for v in freq if v != barrier), key=lambda v: freq[v])
    obj = {(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, barrier)}
    out = [[bg for _ in range(w)] for _ in range(h)]
    moved = set()
    if rowbar is not None:
        out[rowbar] = grid[rowbar][:]
        lo, hi = min(r for r,c in obj), max(r for r,c in obj)
        dr = (rowbar + 1 - lo) if rowbar < lo else (rowbar - 1 - hi)
        moved = {(r+dr,c) for r,c in obj}
        stripe = min(r for r,c in moved)-1 if dr < 0 else max(r for r,c in moved)+1
        if 0 <= stripe < h: out[stripe] = [8]*w
    else:
        for r in range(h): out[r][colbar] = barrier
        lo, hi = min(c for r,c in obj), max(c for r,c in obj)
        dc = (colbar + 1 - lo) if colbar < lo else (colbar - 1 - hi)
        moved = {(r,c+dc) for r,c in obj}
        stripe = min(c for r,c in moved)-1 if dc < 0 else max(c for r,c in moved)+1
        if 0 <= stripe < w:
            for r in range(h): out[r][stripe] = 8
    for r,c in moved:
        out[r][c] = grid[r-dr][c] if rowbar is not None else grid[r][c-dc]
    return out

